def GaussSiedel(mat, roots, eps=0.001, max_iterations=100):
    n = len(mat)
    eps = 0.0000001

    for iter in range(max_iterations):
        flag = False
        for i in range(n):
            x = 0
            for j in range(n):
                if j != i:
                    x += mat[i][j] * roots[j]
            x = (mat[i][n] - x) / mat[i][i]
            e = abs(roots[i] - x)
            if e &gt; eps:
                flag = True
            roots[i] = x
        if not flag:
            break
        print(roots)


